import 'package:flutter/material.dart';
class AppBadge extends StatelessWidget{const AppBadge({super.key,required this.label,required this.color,this.icon});final String label;final Color color;final IconData? icon;@override Widget build(BuildContext context)=>Container(padding:const EdgeInsets.symmetric(horizontal:10,vertical:6),decoration:BoxDecoration(color:color.withValues(alpha:.12),borderRadius:BorderRadius.circular(18)),child:Row(mainAxisSize:MainAxisSize.min,children:[if(icon!=null)...[Icon(icon,size:16,color:color),const SizedBox(width:5)],Text(label,style:TextStyle(color:color,fontWeight:FontWeight.w600))]));}
